create or replace function public.submit_user_report(p_category text,p_subject text,p_description text) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin if auth.uid() is null then raise exception 'unauthorized';end if;if p_category not in('bug','content','account','payment','suggestion','other') then raise exception 'Kategori laporan tidak valid';end if;if char_length(btrim(coalesce(p_subject,'')))<3 then raise exception 'Subjek minimal 3 karakter';end if;if char_length(btrim(coalesce(p_description,'')))<10 then raise exception 'Penjelasan minimal 10 karakter';end if;insert into public.content_reports(reporter_id,category,subject,description,status,priority) values(auth.uid(),p_category,left(btrim(p_subject),160),left(btrim(p_description),4000),'open','normal') returning id into rid;return rid;end$$;
revoke all on function public.submit_user_report(text,text,text) from public,anon;grant execute on function public.submit_user_report(text,text,text) to authenticated;
create or replace function public.get_my_notification_settings() returns jsonb language plpgsql security definer set search_path='' as $$declare r public.user_settings%rowtype;begin if auth.uid() is null then raise exception 'unauthorized';end if;insert into public.user_settings(user_id) values(auth.uid()) on conflict(user_id) do nothing;select * into r from public.user_settings where user_id=auth.uid();return jsonb_build_object('daily_reminder',coalesce(r.daily_reminder,false));end$$;
revoke all on function public.get_my_notification_settings() from public,anon;grant execute on function public.get_my_notification_settings() to authenticated;
create or replace function public.set_my_daily_reminder(p_enabled boolean) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'unauthorized';end if;insert into public.user_settings(user_id,daily_reminder,updated_at) values(auth.uid(),p_enabled,now()) on conflict(user_id) do update set daily_reminder=excluded.daily_reminder,updated_at=now();end$$;
revoke all on function public.set_my_daily_reminder(boolean) from public,anon;grant execute on function public.set_my_daily_reminder(boolean) to authenticated;